// Your policy lives here. Edit this, not the response node.
//
// The Actor returns one record per address; we sent one, so take the first.
// Every field below is guaranteed present — no optional chaining needed,
// which is the whole point of the output contract.

const r = $input.first().json;

if (!r || !r.status) {
  return [{ json: { decision: 'review', reason: 'no verdict returned', status: 'unknown', sub_status: 'internal_error' } }];
}

let decision;
let reason;

if (r.status === 'undeliverable') {
  decision = 'block';
  reason = r.sub_status === 'invalid_syntax' ? 'not a valid address'
    : r.sub_status === 'no_mx_record' ? 'that domain does not accept email'
    : 'no mailbox with that name';
} else if (r.checks.disposable) {
  decision = 'block';
  reason = 'disposable address';
} else if (r.status === 'deliverable') {
  decision = 'allow';
  reason = 'mailbox confirmed';
} else if (r.status === 'unknown') {
  // Could not find out — greylisting, a timeout. Blocking here turns a
  // network hiccup into a lost signup.
  decision = 'review';
  reason = 'could not complete the check, try again later';
} else {
  decision = 'review';
  reason = r.sub_status === 'catch_all' ? 'domain accepts all addresses, mailbox unconfirmed'
    : r.sub_status === 'role_based' ? 'shared inbox, not a person'
    : r.sub_status === 'free_provider_unverifiable' ? 'consumer provider, mailbox unverifiable'
    : r.sub_status === 'full_mailbox' ? 'mailbox is full'
    : r.sub_status;
}

return [{ json: {
  decision,
  reason,
  email: r.email,
  status: r.status,
  sub_status: r.sub_status,
  score: r.score,
  disposable: r.checks.disposable,
  role_based: r.checks.role_based,
  catch_all: r.checks.catch_all
} }];
